using Tern.App.Commands;
namespace Tern.App.Help;
public static partial class FeatureCatalog
{
    private static readonly Tutorial[] Release105Tutorials =
    [
        new("Tern Quick Start and starter templates", ["Welcome offers New note, Open files and Open folder. Secondary actions open a sample, Starter templates or the guide.", "Choose Starter templates, search the ten-template catalog, inspect the preview and choose Use template. Samples and templates use CRLF; Save writes a new file.", "Hide Quick Start tips hides teaching in Welcome and the editor, including after restart. Sample notes, templates and the guide stay available in an empty workspace. Help → Tern Quick Start reopens the same design without clearing that preference.", "The catalog includes Meeting Notes, Project Plan, Task Checklist, Daily Journal, README, Architecture Decision Record, Technical Design, Incident Postmortem, Release Notes and Project Status Report."]),
        new("Add, edit or clear note tags", ["Open Edit note metadata and enter comma-separated tags, for example work, planning.", "Clear tags empties the field. Apply tags changes the note in memory; Save writes the file to disk. Unrelated front matter is preserved.", "Edit metadata in Source remains available, including when complex metadata requires a manual edit. Review your changes before saving."]),
        new("Insert a web, file or heading link", ["Choose Format → Insert Link. Select Web address, Local file or Heading in this note.", "Web address requires a complete http:// or https:// address. Tern validates its form without fetching it.", "For Local file, save the note first so Tern can calculate a relative path. Browse for an existing file. For Heading in this note, choose a heading already present.", "Optional link text defaults to the destination or heading. Choose Insert link when validation succeeds."], CommandIds.InsertLink),
        new("Save before attaching an image", ["For an unsaved note, Tern first explains that saving establishes the attachment folder. Choose Save note or Cancel.", "Save note opens Save As. Only a successful save continues to image selection. Cancel or save failure stops insertion.", "Choose the image and attachment destination. If that image file already exists, check its full path and choose Replace file explicitly or Cancel to keep it.", "Review the image in Reading and Save the note. Undo removes the Markdown link; copied images remain on disk."], CommandIds.InsertImage),
        new("Line endings and character encoding", ["New blank notes, sample notes and starter templates use CRLF. Opened files preserve detected line endings.", "Use the Line endings control in the status bar to convert to CRLF, LF or CR. Save writes the converted text.", "Encoding is separate and controls how characters are stored, for example UTF-8. Choosing a line ending does not change the encoding."]),
        new("Print specific pages", ["File → Print preview renders the same PDF bytes used for printable output, with real page boundaries.", "Navigate to a page and choose Current page, choose All, or enter Pages such as 1-3, 5. Ranges must fit the actual page count. Valid ranges immediately filter the preview. Preview page counts positions in that selection; Document page identifies the original page. Changing the selection clears previous completion messages.", "Choose Open selected PDF. The generated PDF contains only that selection, in original order. Press Ctrl+P in your PDF reader to select the printer, paper and copies.", "Tern does not submit a print job itself. Printer margins and driver scaling can affect the physical result; check the PDF reader settings."], CommandIds.Print),
        new("Install Tern and open Markdown from Explorer", ["Open Tern-1.0.5.msi to start the setup wizard. Review and accept the MIT license, then choose an installation folder your account can write to. Setup installs for the current user.", "Choose whether to add Start menu and desktop shortcuts, review the setup choices and click Install. On the successful completion page, Launch Tern opens the app when you click Finish. Setup registers .md support without changing your default app.", "The standalone Tern.exe runs the editor directly. The portable ZIP must be fully extracted; keep its Tern.exe and companion files together.", "For standalone or ZIP use, open Settings → Windows integration → Register this copy. Keep that copy at a stable path; register again after moving it.", "Right-click a .md file in any folder and choose Open with Tern, under Show more options on Windows 11 classic-menu configurations. This entry applies to one Markdown file, not folders or unrelated file types.", "To double-click with Tern, choose Tern yourself in Windows Open with / Default apps. Installation never changes your existing default."]),
        new("Ask and learn without an AI connection", ["Without a configured AI connection, Ask & learn displays a message before you submit a question.", "Find guide steps searches the installed Tern guides and returns relevant documented steps. It does not generate a conversational answer, inspect arbitrary notes or answer general questions.", "Browse installed guides opens the feature catalog. Manage connections opens AI settings; generated answers require a compatible configured text-generation connection and an explicit send."])
    ];
}
